10	/**
11	 * Is this address already the target of a live DNAT rule on this host? Some
12	 * infrastructure (the shared-hosting node, VM 200) reaches its dedicated IP
13	 * entirely through a whole-IP DNAT rule to an internal address — it has no OVH
14	 * Virtual MAC at all, so the MAC-based check above cannot see it. A real
15	 * incident: this exact IP was one query away from being handed to a game
16	 * server because "no Virtual MAC bound" was mistaken for "free" — it was
17	 * actively carrying production hosting traffic via `iptables -t nat`. Treat
18	 * any address with a live DNAT target as claimed, unconditionally.
19	 */
20	async function hasLiveDnatRule(address: string): Promise<boolean> {
21	  try {
22	    const { stdout } = await execFileP("iptables", ["-t", "nat", "-S", "PREROUTING"]);
23	    return stdout.split("\n").some((line) => line.includes(`-d ${address}/32`) && line.includes("-j DNAT"));
24	  } catch {
25	    // iptables unreadable (permissions, not present, sandboxed test env) — fail
26	    // closed is wrong here (it would make every sync a no-op); fail to "not
27	    // claimed by this specific check" and rely on the Virtual MAC check plus
28	    // the existing DB row remaining authoritative for anything already tracked.
29	    return false;
30	  }
31	}
