159	/**
160	 * Claim a free IP for a server and create its OVH Virtual MAC so the VM can use it.
161	 * Returns the address + virtualMac + gateway, or null if none available.
162	 */
163	export async function allocateDedicatedIp(
164	  serverId: string,
165	  vmid: number
166	): Promise<{ address: string; virtualMac: string; gateway: string } | null> {
167	  if (SANDBOX) {
168	    // Hand out a synthetic dedicated IP without any OVH call or pool mutation.
169	    return { address: sandboxIp(vmid), virtualMac: sandboxMac(vmid), gateway: "198.51.100.254" };
170	  }
171	  // Idempotent per server: PROVISION can retry (up to MAX_ATTEMPTS). If this
172	  // server already holds a fully-allocated dedicated IP (ASSIGNED + a bound
173	  // Virtual MAC), return it instead of claiming a second pool IP — re-claiming
174	  // would leak an IP and P2002 on the unique DedicatedIp.serverId.
175	  const mine = await db.dedicatedIp.findUnique({ where: { serverId } });
176	  if (mine && mine.status === "ASSIGNED" && mine.virtualMac) {
177	    return { address: mine.address, virtualMac: mine.virtualMac, gateway: ovhGateway() };
178	  }
179	  if (!ovhConfigured()) return null;
180	  // Atomically claim a FREE ip. Excluding purpose: INTERNAL here is a second,
181	  // independent guard (alongside the sync-time checks above) against ever
182	  // handing an admin-marked internal IP — e.g. the shared-hosting node, which
183	  // can sit with serverId: null and no live-attribute for allocation to see —
184	  // to a customer server.
185	  const claim = await db.$transaction(async (tx) => {
186	    const ip = await tx.dedicatedIp.findFirst({
187	      where: { status: "FREE", purpose: "CUSTOMER" },
188	      orderBy: { createdAt: "asc" },
189	    });
190	    if (!ip) return null;
191	    await tx.dedicatedIp.update({ where: { id: ip.id }, data: { status: "PENDING", serverId } });
192	    return ip;
193	  });
194	  if (!claim) return null;
195	
196	  try {
197	    // Reuse an existing vMAC for this IP if one is already bound; else create one.
198	    let mac = await findVirtualMacForIp(claim.address);
199	    if (!mac) {
200	      // Creation is asynchronous (returns a task) — kick it off then poll.
201	      await ovhApi.createVirtualMac(SERVER, claim.address, `nxeon-${vmid}`);
202	      for (let i = 0; i < 40 && !mac; i++) {
203	        await new Promise((r) => setTimeout(r, 3000));
204	        mac = await findVirtualMacForIp(claim.address);
205	      }
206	    }
207	    if (!mac) throw new Error("Virtual MAC not bound after creation (OVH task still pending)");
208	    await db.dedicatedIp.update({ where: { id: claim.id }, data: { status: "ASSIGNED", virtualMac: mac } });
209	    return { address: claim.address, virtualMac: mac, gateway: ovhGateway() };
210	  } catch (e) {
211	    // Roll the claim back to FREE on failure
212	    await db.dedicatedIp.update({ where: { id: claim.id }, data: { status: "FREE", serverId: null, virtualMac: null } });
213	    throw e;
214	  }
215	}
