      const mem = typeof stat?.mem === "number" && typeof stat?.maxmem === "number" ? `${fmtBytes(stat.mem)} / ${fmtBytes(stat.maxmem)}` : "—";
      const uptime = typeof stat?.uptime === "number" ? fmtUptime(stat.uptime) : "—";
      lines.push(`${label}\n     CPU ${cpu} · RAM ${mem} · up ${uptime}`);
    } catch {
      lines.push(`${label}\n     (live stats unavailable right now)`);
    }
  }
  return lines.join("\n");
}

