 * orders) — and `lib/game-order.ts`'s game-server order path never called
 * either one at all: it creates its `Server` row with no `nodeId`, so every
 * game server ever ordered falls through `worker/index.ts`'s `nodeFor()`
 * fallback (`server.node ?? primary node`) and lands on the PRIMARY node
 * regardless of its actual load. Confirmed live: `primary` sits at 84% real
 * RAM and 200% committed CPU while other nodes are comparatively idle, and
 * every game server in production has `nodeId: null`. Fixed by giving
 * `game-order.ts` the same real scheduler VPS/NxCloud orders already use,
 * rather than writing a fourth copy or leaving it unscheduled.
 */
export async function scheduleNode(planRamMB: number) {
  const nodes = await db.node.findMany({ where: { enabled: true, status: "ONLINE" } });
  if (nodes.length === 0) return null;
  const loads = await Promise.all(
    nodes.map(async (n) => {
      const agg = await db.server.findMany({
        where: { nodeId: n.id, status: { notIn: ["DELETING"] } },
        select: { plan: { select: { ramMB: true } } },
      });
      const used = agg.reduce((s, r) => s + r.plan.ramMB, 0);
      // Commitment AFTER this VM lands — that's what decides whether placing
      // here tips the node critical.
      const projectedPct = n.capacityRamMB > 0 ? ((used + planRamMB) / n.capacityRamMB) * 100 : 100;
      return { node: n, free: n.capacityRamMB - used, projectedPct };
    }),
  );
  const { critPct } = await nodeThresholds();
  const roomy = loads.filter((l) => l.projectedPct < critPct);
  const pool = roomy.length > 0 ? roomy : loads;
  pool.sort((a, b) => b.free - a.free);
  return pool[0].node;
}

