export default async function AdminIps() {
  await requireArea("fleet");
  const ips: IpRow[] = await db.dedicatedIp.findMany({
    include: { server: { select: { id: true, hostname: true, userId: true } } },
    orderBy: { address: "asc" },
  });
  const customerIps = ips.filter((i) => i.purpose === "CUSTOMER");
  const internalIps = ips.filter((i) => i.purpose === "INTERNAL");
  const free = ips.filter((i) => i.status === "FREE").length;
  const assigned = ips.filter((i) => i.status === "ASSIGNED").length;
  const monthlyCost = ips.length * OVH_IP_UNIT_COST_CENTS;
  // Revenue is per customer-billed IP only. An INTERNAL row (the shared-hosting
  // node, cold-email relay, an owner-operated site) is never charged, so it must
  // not count here even though it's still counted in "Assigned"/"Total IPs"/
  // "OVH cost" above — those track the whole fleet, not just what's billable.
  const billableAssigned = customerIps.filter((i) => i.status === "ASSIGNED").length;
  const monthlyRevenue = billableAssigned * DEDICATED_IP_PRICE_CENTS;

  return (
    <div className="space-y-6">
      <PageHeader title="Dedicated IP pool" sub="Public IPv4 addresses synced from OVH and assigned to customer VMs.">
        {ovhConfigured() && <SyncIpPoolButton />}
      </PageHeader>

      {!ovhConfigured() ? (
        <div className="card border-amber-500/30">
          <Badge tone="amber">OVH not configured</Badge>
          <p className="mt-2 text-sm text-slate-400">

  ? nodeRow?.storageHdd ?? "vmdata-hdd"
  : nodeRow?.storageNvme ?? "vmdata";

// Pick a vmid that does NOT still own a previous tenant's backup archives.
// `/cluster/nextid` hands back the lowest FREE id, and nothing reaps a deleted
// server's vzdump archives, so the id freed by a deletion comes back carrying
// the old owner's backups — which every backup surface then attributes to the
// new customer (listBackups/requestRestore key on vmid alone). See
// `pickProvisionVmid` in lib/proxmox.ts. Only for a FRESH allocation: a retry
// keeps the vmid already persisted on the row.
const vmid = server.vmid ?? (await allocateFreshVmid(conn));

// The password must be generated ONCE per VM, not once per attempt. cloud-init's
// cc_set_passwords module is `frequency: once-per-instance` — it applies whatever
// cipassword was baked into the FIRST boot's snippet and never re-applies on a
// later config change unless the guest gets a brand-new instance-id. A retried
// PROVISION (server.vmid already set = the clone below is skipped as
// `vmAlreadyExists`, so the guest never reboots) used to call generatePassword()
// again anyway and overwrite Server.rootPasswordEnc with a value the running VM
// never saw — every later SSH from the platform (control panel, GAME_POWER,
// mods, backups) then authenticated with a password that does not match
// /etc/shadow on the guest, failing with "All configured authentication methods
// failed" (confirmed live on a real customer server: 2 attempts, 0 accepted
// logins ever, until the guest's password was force-resynced via the QGA
// set-user-password path). Reuse the already-stored password whenever this
// server already has a vmid (meaning some earlier attempt may have already
// cloned + booted it); only a truly first attempt mints a new one.
const password = server.vmid ? (serverRootPassword(server) ?? generatePassword()) : generatePassword();

// Dedicated public IPv4 (OVH failover + Virtual MAC on the public bridge) vs shared NAT.
// VPS: the global `dedicated_ip_default` setting acts as a platform-wide default (included
// on every plan unless the admin switches it off). Game servers: the customer must
// explicitly purchase the addon at checkout — game orders set `wantsDedicatedIp` from the
// intent, so the global default must NOT override it (that was silently granting free IPs).
let dedicated: { address: string; virtualMac: string; gateway: string } | null = null;
const { getSettingBool: _settingBool } = await import("../lib/settings");
const isGame = !!server.gamePlanId;
const wantDedicated = isGame
  ? server.wantsDedicatedIp
  : server.wantsDedicatedIp || (await _settingBool("dedicated_ip_default", true));
if (wantDedicated && ovhConfigured()) {
  try {
    // Idempotent: on a PROVISION retry (VM may already exist) this returns the
    // server's already-ASSIGNED IP rather than claiming a second pool IP.
    dedicated = await allocateDedicatedIp(server.id, vmid);
  } catch (e) {
    console.error("[worker] dedicated IP allocation failed, falling back to NAT", e);
  }
}
// Node-aware + transactionally-claimed allocation (passing the server id enables
// the claim path, so two concurrent provisions can't pick the same IP/port).

  if (server.vmid) await destroyVm(conn, server.vmid);
  await provision(job);
}

async function suspend(job: Job, unsuspend: boolean) {
  const server = await loadServer(job);
  if (SANDBOX) {
    if (unsuspend) {
      await db.server.update({ where: { id: server.id }, data: { status: "RUNNING", suspendedNote: null, suspendReason: null } });
    } else {
      await db.server.update({ where: { id: server.id }, data: { status: "SUSPENDED" } });
    }
    return;
  }
  const { conn, row: nodeRow } = await nodeFor(server);
  if (unsuspend) {
    // The dedicated IP was returned to the pool while suspended — re-allocate one
    // and reconfigure the public network before starting the VM back up.
    if (server.vmid) {
      const { getSettingBool: _sb } = await import("../lib/settings");
      const isGameSrv = !!server.gamePlanId;
      const wantDedicated = isGameSrv
        ? server.wantsDedicatedIp
        : server.wantsDedicatedIp || (await _sb("dedicated_ip_default", true));
      const alreadyHas = await db.dedicatedIp.findFirst({ where: { serverId: server.id } });
      let reconfigured = alreadyHas ? true : false;
      if (wantDedicated && ovhConfigured() && !alreadyHas) {
        try {
          const d = await allocateDedicatedIp(server.id, server.vmid);
          if (d) {
            await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
              net0: `virtio=${d.virtualMac},bridge=vmbr0`,
              ipconfig0: `ip=${d.address}/32,gw=${d.gateway}`,
            });
            await db.server.update({ where: { id: server.id }, data: { ipAddress: d.address, sshPort: null } });
            reconfigured = true;

